fn search(&mut self, layout: &Layout, index: &WordIndex) -> SearchResult {
    let mut chosen: Option<(usize, Vec<usize>)> = None;
    for slot in &layout.slots {
        if self.state.words[slot.index].is_some() { continue; }
        let words = self.candidates(slot, index);
        if chosen.as_ref().is_none_or(|(_, previous)| words.len() < previous.len()) { chosen = Some((slot.index, words)); }
    }
    let Some((number, words)) = chosen else { return SearchResult::Complete; };
    if words.is_empty() { self.dead_ends += 1; self.failures[number] += 1; return SearchResult::Fail; }
    let slot = &layout.slots[number];
    for word in words {
        if self.nodes == self.budget { return SearchResult::Abort; }
        self.nodes += 1;
        let filled = self.state.assign(slot, word, index);
        self.sequence.push(number);
        let wiped = slot.crossings.iter().copied().find(|&other| self.state.words[other].is_none() && self.candidates(&layout.slots[other], index).is_empty());
        let result = if let Some(other) = wiped {
            self.prunes += 1; self.failures[other] += 1; SearchResult::Fail
        } else {
            if self.sequence.len() > self.max_depth { self.max_depth = self.sequence.len(); self.best = self.state.clone(); }
            self.search(layout, index)
        };
        if result != SearchResult::Fail { return result; }
        self.state.unassign(slot, &filled);
    for slot in &mut result.slots {
        let owners = if slot.across { &result.down_slot } else { &result.across_slot };
        slot.crossings = slot.cells.iter().filter_map(|&cell| owners[cell]).collect();
        slot.crossings.sort_unstable();
    entries.sort_by_key(|(word, score)| (Reverse(*score), word.clone()));
    let mut result = Self { words: Vec::new(), lookup: BTreeMap::new(), by_length: BTreeMap::new(), by_letter: BTreeMap::new() };
    for (id, (text, score)) in entries.into_iter().enumerate() {
        let letters = text.as_bytes().to_vec();
        result.lookup.insert(text.clone(), id);
        result.by_length.entry(letters.len()).or_default().push(id);
        for (position, &letter) in letters.iter().enumerate() { result.by_letter.entry((letters.len(), position, letter)).or_default().push(id); }
        result.words.push(Word { text, letters, score });
    }
    result
pub fn candidates(&self, pattern: &[u8], minimum: i64, used: &BTreeSet<usize>) -> Vec<usize> {
    let empty = Vec::new();
    let mut pool = self.by_length.get(&pattern.len()).unwrap_or(&empty);
    for (position, &mark) in pattern.iter().enumerate() {
        if mark == b'.' { continue; }
        let bucket = self.by_letter.get(&(pattern.len(), position, mark)).unwrap_or(&empty);
        if bucket.len() < pool.len() { pool = bucket; }
    }
    pool.iter().copied().take_while(|&id| self.words[id].score >= minimum)
        .filter(|id| !used.contains(id) && matches(&self.words[*id].letters, pattern)).collect()
}
